    "_%n open report._::_%n open reports._" : ["%n otvorena prijava.","%n otvorene prijave.","%n otvorenih prijava."],
    "_%n resolved report_::_%n resolved reports_" : ["%n riješena prijava","%n riješene prijave","%n riješenih prijava"],
    "Reported account" : "Prijavljeni račun",
    "Reporter" : "Prijavio",
